css:
.mp-page { height: 100dvh; overflow: hidden; display: grid; place-content: center; gap: 16px; padding: 32px; background: var(--mp-panel); color: var(--mp-ink); }
h1 { margin: 0; font-size: clamp(22px, 3vw, 36px); }
p { margin: 0; color: var(--mp-muted); }
button { border: 1px solid var(--mp-border-strong); border-radius: 999px; padding: 8px 18px; background: var(--mp-raised); color: var(--mp-ink); }
.mp-tall { height: 1800px; background: var(--mp-raised); border: 1px solid var(--mp-border); }

